from typing import List

class Solution:
    def combine(self, n: int, k: int) -> List[List[int]]:
        result = []
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            combo = []
            for i in range(n):
                if mask & (1 << i):
                    combo.append(i + 1)
            result.append(combo)
        return result

